CREATE TABLE organizations(id uuid PRIMARY KEY, name text NOT NULL, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE users(id uuid PRIMARY KEY, display_name text NOT NULL, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE external_identities(issuer text NOT NULL, subject text NOT NULL, user_id uuid NOT NULL REFERENCES users(id), PRIMARY KEY(issuer,subject));
CREATE TABLE roles(id text PRIMARY KEY);
INSERT INTO roles VALUES ('owner'),('administrator'),('marketing_manager'),('editor'),('approver'),('analyst'),('viewer');
CREATE TABLE permissions(id text PRIMARY KEY);
INSERT INTO permissions VALUES ('brands.read'),('brands.create'),('brands.write');
CREATE TABLE role_permissions(role_id text REFERENCES roles(id), permission_id text REFERENCES permissions(id), PRIMARY KEY(role_id,permission_id));
INSERT INTO role_permissions SELECT id,'brands.read' FROM roles;
INSERT INTO role_permissions SELECT id,'brands.create' FROM roles WHERE id IN ('owner','administrator','marketing_manager');
INSERT INTO role_permissions SELECT id,'brands.write' FROM roles WHERE id IN ('owner','administrator','marketing_manager','editor');
CREATE TABLE organization_members(org_id uuid REFERENCES organizations(id),user_id uuid REFERENCES users(id),active boolean NOT NULL DEFAULT true,authz_revision bigint NOT NULL DEFAULT 1,PRIMARY KEY(org_id,user_id));
CREATE TABLE user_roles(org_id uuid,user_id uuid,role_id text NOT NULL REFERENCES roles(id), PRIMARY KEY(org_id,user_id), FOREIGN KEY(org_id,user_id) REFERENCES organization_members(org_id,user_id));
CREATE TABLE brands(org_id uuid REFERENCES organizations(id),id uuid NOT NULL,name text NOT NULL CHECK(length(btrim(name)) BETWEEN 1 AND 120),description text NOT NULL DEFAULT '' CHECK(length(description)<=4000),website text NOT NULL DEFAULT '' CHECK(length(website)<=2048),status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','archived')),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(org_id,id));
CREATE TABLE user_brand_access(org_id uuid,brand_id uuid,user_id uuid,active boolean NOT NULL DEFAULT true,PRIMARY KEY(org_id,brand_id,user_id),FOREIGN KEY(org_id,brand_id) REFERENCES brands(org_id,id),FOREIGN KEY(org_id,user_id) REFERENCES organization_members(org_id,user_id));
CREATE INDEX user_brand_access_user ON user_brand_access(org_id,user_id) WHERE active;
CREATE TABLE sessions(token_hash text PRIMARY KEY CHECK(length(token_hash)=64),org_id uuid NOT NULL,user_id uuid NOT NULL,authz_revision bigint NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),idle_expires_at timestamptz NOT NULL,absolute_expires_at timestamptz NOT NULL,revoked_at timestamptz,FOREIGN KEY(org_id,user_id) REFERENCES organization_members(org_id,user_id),CHECK(idle_expires_at<=absolute_expires_at));
CREATE INDEX sessions_expiry ON sessions(absolute_expires_at);
CREATE TABLE oidc_login_requests(state_hash text PRIMARY KEY,binding_hash text NOT NULL,nonce text NOT NULL,verifier text NOT NULL,expires_at timestamptz NOT NULL);
CREATE INDEX oidc_login_expiry ON oidc_login_requests(expires_at);
CREATE TABLE audit_logs(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,org_id uuid,user_id uuid,event text NOT NULL CHECK(event IN ('login.success','login.failure','logout','session.revoked','brand.created','brand.updated','brand.archived','identity.provisioned')),resource_id uuid,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(org_id,user_id) REFERENCES organization_members(org_id,user_id));
CREATE INDEX audit_logs_org_time ON audit_logs(org_id,created_at);
